const {test,assert,path,root,vue,loader,mount,tick,clone,deferred,ticket,all,text,pageFile}=require('./helpers/diy-list-runtime.cjs');
const editor=path.join(root,'components/content/DiyPointsEditor.vue'),preview=path.join(root,'components/content/DiyPointsPreview.vue'),util=path.join(root,'utils/diyPointsEditor.ts');
