function harness(value=[fresh()],options={}){const l=loader(options),props=vue.reactive({modelValue:JSON.stringify(value),editorKey:'points:2',pageId:2,disabled:false,...options.props}),writes=[],m=mount(l,editor,props,(_n,raw)=>{writes.push(raw);props.modelValue=raw;});return{...l,...m,props,writes,value:()=>JSON.parse(props.modelValue)};}
