async function fetches(send,work){const previous=global.fetch;global.fetch=send;try{await work();}finally{global.fetch=previous;}}
function button(r,label){const n=all(r.tree,n=>n.props['data-element']==='el-button'&&text(n).trim()===label)[0];assert.ok(n,label);return n;}

